    loaded_at_field: _loaded_at
    freshness:
      warn_after: {count: 6, period: hour}
      error_after: {count: 12, period: hour}
    tables: [{name: payments}]`}),e.jsxs("p",{children:["Each generic test compiles to a SELECT of violating rows, just like the cards above. ",e.jsx("code",{children:"dbt build"})," runs models and tests in DAG order and skips downstream models when a test with severity error fails. ",e.jsx("code",{children:"dbt source freshness"})," checks sources; ",e.jsx("code",{children:"dbt_utils"})," and ",e.jsx("code",{children:"dbt-expectations"})," add many generic tests; singular tests are plain .sql files; unit tests (dbt 1.8+) test model logic on fixed inputs."]})]})},{label:"Great Expectations",content:e.jsxs(e.Fragment,{children:[e.jsx(j,{lang:"py",title:"Great Expectations (GX Core, sketch)",code:`
